        }

      wait_until = now;
      probe_timespec_add_ms(&wait_until, PROBE_IMU_FIFO_WATCHDOG_MS);

      do
        {
          wait_status = sem_clockwait(&g_imu_drdy_sem, CLOCK_MONOTONIC,
                                      &wait_until);
