      while (wait_status < 0 && errno == EINTR);

      if (wait_status < 0)
        {
          if (errno == ETIMEDOUT)
            {
              timeouts++;
              timeout_status_polls++;
              ret = probe_imu_read(fd, PROBE_IMU_ADDR,
                                   PROBE_IMU_FIFO_STATUS1,
                                   status, sizeof(status));
              if (ret != 0)
                {
                  i2c_errors++;
                  expected_valid = false;
                  continue;
                }

              status_ready = true;
              if ((status[1] & 0x60) == 0 &&
                  ((status[1] & 0x10) != 0 ||
                   probe_imu_fifo_depth(status) == 0))
