 100	async def wait_for_control(control_queue, subtype, token, timeout=5.0):
 101	    deadline = asyncio.get_running_loop().time() + timeout
 102	    while True:
 103	        remaining = deadline - asyncio.get_running_loop().time()
 104	        if remaining <= 0:
 105	            raise TimeoutError(f"timed out waiting for control subtype {subtype}")
 106	        frame = await asyncio.wait_for(control_queue.get(), remaining)
 107	        if frame["subtype"] == subtype and frame["session_token"] == token:
 108	            return frame
