 586	
 587	static void probe_capture_submit(const struct probe_imu_sample *sample)
 588	{
 589	  struct probe_capture_sample_s *capture;
 590	  uint32_t generation;
 591	  uint32_t head;
 592	  uint32_t tail;
 593	
 594	  if (!__atomic_load_n(&g_capture_active, __ATOMIC_ACQUIRE))
 595	    {
 596	      return;
 597	    }
 598	
 599	  generation = __atomic_load_n(&g_capture_generation, __ATOMIC_RELAXED);
 600	  if (generation !=
 601	      __atomic_load_n(&g_connection_generation, __ATOMIC_ACQUIRE))
 602	    {
 603	      return;
 604	    }
 605	
 606	  __atomic_fetch_add(&g_capture_generated, 1, __ATOMIC_RELAXED);
 607	  __atomic_store_n(&g_capture_last_sequence, sample->sequence,
 608	                   __ATOMIC_RELAXED);
 609	  if ((sample->flags & PROBE_IMU_SAMPLE_FLAG_GAP) != 0)
 610	    {
 611	      __atomic_fetch_add(&g_capture_gap_samples, 1, __ATOMIC_RELAXED);
 612	    }
 613	
 614	  head = __atomic_load_n(&g_capture_head, __ATOMIC_RELAXED);
 615	  tail = __atomic_load_n(&g_capture_tail, __ATOMIC_ACQUIRE);
 616	  if (head - tail >= PROBE_CAPTURE_QUEUE_DEPTH)
 617	    {
 618	      __atomic_fetch_add(&g_capture_queue_full, 1, __ATOMIC_RELAXED);
 619	      return;
 620	    }
 621	
 622	  capture = &g_capture_queue[head % PROBE_CAPTURE_QUEUE_DEPTH];
 623	  capture->connection_generation = generation;
 624	  capture->sequence = sample->sequence;
 625	  capture->uptime_ms = (uint32_t)(sample->monotonic_us / 1000ULL);
 626	  memcpy(capture->accel, sample->accel, sizeof(capture->accel));
 627	  capture->flags = (uint8_t)sample->flags;
 628	  if (!__atomic_load_n(&g_capture_active, __ATOMIC_ACQUIRE) ||
 629	      generation !=
 630	        __atomic_load_n(&g_capture_generation, __ATOMIC_RELAXED))
 631	    {
 632	      return;
 633	    }
 634	
 635	  __atomic_store_n(&g_capture_head, head + 1, __ATOMIC_RELEASE);
 636	  __atomic_fetch_add(&g_capture_enqueued, 1, __ATOMIC_RELAXED);
 637	  sem_post(&g_rx_sem);
 638	}
