1719	static void probe_put_le64(uint8_t *value, uint64_t number)
1720	{
1721	  value[0] = (uint8_t)number;
1722	  value[1] = (uint8_t)(number >> 8);
1723	  value[2] = (uint8_t)(number >> 16);
1724	  value[3] = (uint8_t)(number >> 24);
1725	  value[4] = (uint8_t)(number >> 32);
1726	  value[5] = (uint8_t)(number >> 40);
1727	  value[6] = (uint8_t)(number >> 48);
1728	  value[7] = (uint8_t)(number >> 56);
1729	}
