1731	static uint16_t probe_crc16_ccitt_false(const uint8_t *value, size_t length)
1732	{
1733	  uint16_t crc = 0xffff;
1734	  size_t i;
1735	  uint8_t bit;
1736	
1737	  for (i = 0; i < length; i++)
1738	    {
1739	      crc ^= (uint16_t)value[i] << 8;
1740	      for (bit = 0; bit < 8; bit++)
1741	        {
1742	          crc = (crc & 0x8000) != 0 ?
1743	                (uint16_t)((crc << 1) ^ 0x1021) :
1744	                (uint16_t)(crc << 1);
1745	        }
1746	    }
1747	
1748	  return crc;
1749	}
