1788	static void probe_capture_drain(uint32_t generation, uint32_t limit)
1789	{
1790	  struct probe_capture_sample_s sample;
1791	  uint8_t frame[PROBE_CAPTURE_SAMPLE_SIZE];
1792	  uint32_t count = 0;
1793	  bt_status_t status;
1794	
1795	  while (count < limit && probe_capture_take(&sample))
1796	    {
1797	      count++;
1798	      if (sample.connection_generation != generation)
1799	        {
1800	          continue;
1801	        }
1802	
1803	      frame[0] = PROBE_CAPTURE_SAMPLE_TYPE;
1804	      frame[1] = PROBE_CAPTURE_PROTOCOL_VERSION;
1805	      frame[2] = sample.flags;
1806	      probe_put_le32(&frame[3], sample.sequence);
1807	      probe_put_le32(&frame[7], sample.uptime_ms);
1808	      probe_put_le16(&frame[11], (uint16_t)sample.accel[0]);
1809	      probe_put_le16(&frame[13], (uint16_t)sample.accel[1]);
1810	      probe_put_le16(&frame[15], (uint16_t)sample.accel[2]);
1811	      status = probe_notify(g_service_handle, frame, sizeof(frame));
1812	      if (status == BT_STATUS_SUCCESS)
1813	        {
1814	          __atomic_fetch_add(&g_capture_notify_success, 1,
1815	                             __ATOMIC_RELAXED);
1816	        }
1817	      else
1818	        {
1819	          __atomic_fetch_add(&g_capture_notify_failure, 1,
1820	                             __ATOMIC_RELAXED);
1821	        }
1822	    }
1823	}
