1928	static void probe_capture_stop(uint32_t session_id,
1929	                               uint32_t connection_generation)
1930	{
1931	  uint32_t values[3];
1932	  uint32_t recovery;
1933	
1934	  if (!__atomic_load_n(&g_capture_active, __ATOMIC_ACQUIRE) ||
1935	      session_id != g_capture_session_id ||
1936	      connection_generation !=
1937	        __atomic_load_n(&g_capture_generation, __ATOMIC_RELAXED))
1938	    {
1939	      probe_capture_control(5, 2, session_id, NULL, 0);
1940	      return;
1941	    }
1942	
1943	  __atomic_store_n(&g_capture_active, false, __ATOMIC_RELEASE);
1944	  probe_capture_drain(connection_generation, UINT32_MAX);
1945	  recovery =
1946	    __atomic_load_n(&g_fifo_recovery_total, __ATOMIC_RELAXED) -
1947	    g_capture_fifo_recovery_start;
1948	
1949	  values[0] = __atomic_load_n(&g_capture_generated, __ATOMIC_RELAXED);
1950	  values[1] = __atomic_load_n(&g_capture_enqueued, __ATOMIC_RELAXED);
1951	  values[2] = __atomic_load_n(&g_capture_queue_full, __ATOMIC_RELAXED);
1952	  probe_capture_control(2, 0, session_id, values, 3);
1953	  values[0] = __atomic_load_n(&g_capture_notify_success, __ATOMIC_RELAXED);
1954	  values[1] = __atomic_load_n(&g_capture_notify_failure, __ATOMIC_RELAXED);
1955	  values[2] = __atomic_load_n(&g_capture_gap_samples, __ATOMIC_RELAXED);
1956	  probe_capture_control(3, 0, session_id, values, 3);
1957	  values[0] = __atomic_load_n(&g_capture_last_sequence, __ATOMIC_RELAXED);
1958	  values[1] = recovery;
1959	  probe_capture_control(4, 0, session_id, values, 2);
1960	  probe_capture_control(5, 0, session_id, NULL, 0);
1961	  probe_capture_print_stats("stopped");
1962	}
