2653	static void *probe_communication_thread(void *arg)
2654	{
2655	  struct probe_game_result game_result;
2656	  struct probe_rx_slot_s slot;
2657	  bt_address_t peer_addr;
2658	  uint32_t generation;
2659	  uint32_t active_generation = 0;
2660	  uint32_t head;
2661	  uint32_t tail;
2662	  bool connected;
2663	  bool have_slot;
2664	  int wait_status;
2665	  struct timespec wait_until;
2666	
2667	  (void)arg;
2668	
2669	  for (;;)
2670	    {
2671	      if (clock_gettime(CLOCK_REALTIME, &wait_until) < 0)
2672	        {
2673	          continue;
2674	        }
2675	
2676	      wait_until.tv_nsec += PROBE_GESTURE_WORKER_POLL_MS * 1000000L;
2677	      if (wait_until.tv_nsec >= 1000000000L)
2678	        {
2679	          wait_until.tv_sec++;
2680	          wait_until.tv_nsec -= 1000000000L;
2681	        }
2682	
2683	      do
2684	        {
2685	          wait_status = sem_timedwait(&g_rx_sem, &wait_until);
2686	        }
2687	      while (wait_status < 0 && errno == EINTR);
2688	
2689	      if (wait_status < 0 && errno != ETIMEDOUT)
2690	        {
2691	          continue;
2692	        }
2693	
2694	      tail = __atomic_load_n(&g_rx_tail, __ATOMIC_RELAXED);
2695	      head = __atomic_load_n(&g_rx_head, __ATOMIC_ACQUIRE);
2696	      have_slot = tail != head;
2697	      if (have_slot)
2698	        {
2699	          memcpy(&slot, &g_rx_queue[tail % PROBE_RX_QUEUE_DEPTH],
2700	                 sizeof(slot));
2701	          __atomic_store_n(&g_rx_tail, tail + 1, __ATOMIC_RELEASE);
2702	        }
2703	
2704	      pthread_mutex_lock(&g_state_lock);
2705	      generation = __atomic_load_n(&g_connection_generation,
2706	                                   __ATOMIC_ACQUIRE);
2707	      connected = g_peer_connected;
2708	      memcpy(&peer_addr, &g_peer_addr, sizeof(peer_addr));
2709	      pthread_mutex_unlock(&g_state_lock);
2710	
2711	      if (generation != active_generation)
2712	        {
2713	          if (__atomic_exchange_n(&g_capture_active, false,
2714	                                  __ATOMIC_ACQ_REL))
2715	            {
2716	              probe_capture_print_stats("generation_changed");
2717	            }
2718	
2719	          __atomic_store_n(&g_capture_tail,
2720	                           __atomic_load_n(&g_capture_head,
2721	                                           __ATOMIC_ACQUIRE),
2722	                           __ATOMIC_RELEASE);
2723	          memset(&g_throughput, 0, sizeof(g_throughput));
2724	          memset(&g_reliable39, 0, sizeof(g_reliable39));
2725	          active_generation = generation;
2726	        }
2727	
2728	      if (have_slot &&
2729	          (!connected || slot.connection_generation != generation ||
2730	           memcmp(&slot.addr, &peer_addr, sizeof(peer_addr)) != 0))
2731	        {
2732	          __atomic_fetch_add(&g_rx_stale, 1, __ATOMIC_RELAXED);
2733	          have_slot = false;
2734	        }
2735	
2736	      if (have_slot)
2737	        {
2738	          probe_process_frame(g_service_handle, slot.value, slot.length,
2739	                              generation);
2740	        }
2741	
2742	      probe_capture_drain(generation, 16);
2743	
2744	      while (probe_game_take_ble_result(&game_result))
2745	        {
2746	          int publish_status;
2747	
2748	          if (!connected || game_result.connection_generation != generation)
2749	            {
2750	              printf("openvela_ble_probe: stale game result dropped"
2751	                     " generation=%lu current=%lu\n",
2752	                     (unsigned long)game_result.connection_generation,
2753	                     (unsigned long)generation);
2754	              continue;
2755	            }
2756	
