 38	static bool probe_game_take_imu(struct probe_imu_sample *sample)
 39	{
 40	  uint32_t tail = __atomic_load_n(&g_imu_tail, __ATOMIC_RELAXED);
 41	  uint32_t head = __atomic_load_n(&g_imu_head, __ATOMIC_ACQUIRE);
 42	
 43	  if (tail == head)
 44	    {
 45	      return false;
 46	    }
 47	
 48	  memcpy(sample, &g_imu_ring[tail % PROBE_IMU_RING_DEPTH], sizeof(*sample));
 49	  __atomic_store_n(&g_imu_tail, tail + 1, __ATOMIC_RELEASE);
 50	  return true;
 51	}
 52	
 53	static bool probe_game_take_command(struct probe_game_command *command)
 54	{
 55	  uint32_t tail = __atomic_load_n(&g_command_tail, __ATOMIC_RELAXED);
 56	  uint32_t head = __atomic_load_n(&g_command_head, __ATOMIC_ACQUIRE);
 57	
 58	  if (tail == head)
 59	    {
 60	      return false;
 61	    }
 62	
 63	  memcpy(command, &g_command_ring[tail % PROBE_COMMAND_RING_DEPTH],
 64	         sizeof(*command));
 65	  __atomic_store_n(&g_command_tail, tail + 1, __ATOMIC_RELEASE);
 66	  return true;
 67	}
 68	
 69	static enum probe_judgement_e probe_test_judgement(uint8_t gesture)
 70	{
 71	  /* Test-only visible mapping; this is not an action recognition algorithm. */
 72	
 73	  if (gesture == 1)
 74	    {
 75	      return PROBE_JUDGEMENT_GOOD;
 76	    }
 77	
 78	  if (gesture == 2)
 79	    {
 80	      return PROBE_JUDGEMENT_MISS;
 81	    }
 82	
 83	  return PROBE_JUDGEMENT_PERFECT;
 84	}
