 86	static void probe_game_publish_result(const struct probe_game_result *result,
 87	                                      uint64_t imu_samples,
 88	                                      uint32_t imu_gaps)
 89	{
 90	  struct probe_ui_result ui;
 91	
 92	  ui.judgement = probe_test_judgement(result->gesture);
 93	  ui.combo = result->combo;
 94	  ui.imu_samples = imu_samples;
 95	  ui.imu_gaps = imu_gaps;
 96	
 97	  probe_local_feedback(result);
 98	  if (!probe_ui_submit(&ui))
 99	    {
100	      __atomic_fetch_add(&g_ui_ring_full, 1, __ATOMIC_RELAXED);
101	    }
102	
103	  if (!probe_game_submit_judgement(result))
104	    {
105	      __atomic_fetch_add(&g_result_ring_full, 1, __ATOMIC_RELAXED);
106	    }
107	}
