171	int probe_game_start(void)
172	{
173	  int ret;
174	
175	  if (__atomic_exchange_n(&g_started, true, __ATOMIC_ACQ_REL))
176	    {
177	      return 0;
178	    }
179	
180	  if (sem_init(&g_game_sem, 0, 0) < 0)
181	    {
182	      __atomic_store_n(&g_started, false, __ATOMIC_RELEASE);
183	      return -errno;
184	    }
185	
186	  ret = pthread_create(&g_game_thread, NULL, probe_game_thread, NULL);
187	  if (ret != 0)
188	    {
189	      sem_destroy(&g_game_sem);
190	      __atomic_store_n(&g_started, false, __ATOMIC_RELEASE);
191	      return -ret;
192	    }
193	
194	  pthread_detach(g_game_thread);
195	  return 0;
196	}
