201	  uint32_t tail = __atomic_load_n(&g_imu_tail, __ATOMIC_ACQUIRE);
202	
203	  if (!__atomic_load_n(&g_started, __ATOMIC_ACQUIRE))
204	    {
205	      return false;
206	    }
207	
208	  if (head - tail >= PROBE_IMU_RING_DEPTH)
209	    {
