159	async def wait_for_control(control_queue, subtype, token, timeout=5.0):
160	    deadline = asyncio.get_running_loop().time() + timeout
161	    while True:
162	        remaining = deadline - asyncio.get_running_loop().time()
163	        if remaining <= 0:
164	            raise TimeoutError(f"timed out waiting for control subtype {subtype}")
165	        frame = await asyncio.wait_for(control_queue.get(), remaining)
166	        if frame["subtype"] == subtype and frame["session_token"] == token:
167	            return frame
