 69	static enum probe_judgement_e probe_test_judgement(uint8_t gesture)
 70	{
 71	  /* Test-only visible mapping; this is not an action recognition algorithm. */
 72	
 73	  if (gesture == 1)
 74	    {
 75	      return PROBE_JUDGEMENT_GOOD;
 76	    }
 77	
 78	  if (gesture == 2)
 79	    {
 80	      return PROBE_JUDGEMENT_MISS;
 81	    }
 82	
 83	  return PROBE_JUDGEMENT_PERFECT;
 84	}
