109	static void *probe_game_thread(void *arg)
110	{
111	  struct probe_imu_sample sample;
112	  struct probe_game_command command;
113	  struct probe_game_result result;
114	  uint64_t imu_samples = 0;
115	  uint64_t last_sample_us = 0;
116	  uint32_t imu_gaps = 0;
117	  uint32_t game_session = 1;
118	  uint32_t combo = 0;
119	
120	  (void)arg;
121	  printf("openvela_ble_probe: game thread entered\n");
122	
123	  for (;;)
124	    {
125	      while (sem_wait(&g_game_sem) < 0 && errno == EINTR)
126	        {
127	        }
128	
129	      while (probe_game_take_imu(&sample))
130	        {
131	          imu_samples++;
132	          last_sample_us = sample.monotonic_us;
133	          if ((sample.flags & PROBE_IMU_SAMPLE_FLAG_GAP) != 0)
134	            {
135	              imu_gaps++;
136	            }
137	        }
138	
139	      while (probe_game_take_command(&command))
140	        {
141	          memset(&result, 0, sizeof(result));
142	          result.monotonic_us = last_sample_us;
143	          result.connection_generation = command.connection_generation;
144	          result.gesture = command.gesture;
145	          result.confidence = command.confidence;
146	          result.flags = command.flags;
147	          result.battery = command.battery;
148	          result.game_session = game_session;
149	          result.timing_error_ms = 0;
150	          if (probe_test_judgement(command.gesture) == PROBE_JUDGEMENT_MISS)
151	            {
152	              combo = 0;
153	            }
154	          else
155	            {
156	              combo++;
157	            }
158	
159	          result.combo = combo;
160	          probe_game_publish_result(&result, imu_samples, imu_gaps);
161	          printf("openvela_ble_probe: game test judgement gesture=%u"
162	                 " combo=%lu imu_time_us=%" PRIu64 "\n",
163	                 command.gesture, (unsigned long)combo,
164	                 last_sample_us);
165	        }
166	    }
167	
168	  return NULL;
169	}
