198	bool probe_game_submit_imu(const struct probe_imu_sample *sample)
199	{
200	  uint32_t head = __atomic_load_n(&g_imu_head, __ATOMIC_RELAXED);
201	  uint32_t tail = __atomic_load_n(&g_imu_tail, __ATOMIC_ACQUIRE);
202	
203	  if (!__atomic_load_n(&g_started, __ATOMIC_ACQUIRE))
204	    {
205	      return false;
206	    }
207	
208	  if (head - tail >= PROBE_IMU_RING_DEPTH)
209	    {
210	      __atomic_fetch_add(&g_imu_ring_full, 1, __ATOMIC_RELAXED);
211	      return false;
212	    }
213	
214	  memcpy(&g_imu_ring[head % PROBE_IMU_RING_DEPTH], sample, sizeof(*sample));
215	  __atomic_store_n(&g_imu_head, head + 1, __ATOMIC_RELEASE);
216	  if ((sample->flags & PROBE_IMU_SAMPLE_FLAG_GAP) != 0)
217	    {
218	      __atomic_fetch_add(&g_imu_gap_samples, 1, __ATOMIC_RELAXED);
219	    }
220	
221	  sem_post(&g_game_sem);
222	  return true;
223	}
