225	bool probe_game_submit_command(const struct probe_game_command *command)
226	{
227	  uint32_t head = __atomic_load_n(&g_command_head, __ATOMIC_RELAXED);
228	  uint32_t tail = __atomic_load_n(&g_command_tail, __ATOMIC_ACQUIRE);
229	
230	  if (!__atomic_load_n(&g_started, __ATOMIC_ACQUIRE))
231	    {
232	      return false;
233	    }
234	
235	  if (head - tail >= PROBE_COMMAND_RING_DEPTH)
236	    {
237	      __atomic_fetch_add(&g_command_ring_full, 1, __ATOMIC_RELAXED);
238	      return false;
239	    }
240	
241	  memcpy(&g_command_ring[head % PROBE_COMMAND_RING_DEPTH], command,
242	         sizeof(*command));
243	  __atomic_store_n(&g_command_head, head + 1, __ATOMIC_RELEASE);
244	  sem_post(&g_game_sem);
245	  return true;
246	}
