140	def log_stage_failure(stage, exc):
141	    codes = exception_codes(exc)
142	    detail = f"type={type(exc)!r} repr={exc!r}"
143	    if codes:
144	        detail += " windows_codes=" + repr(codes)
145	    log_stage(stage, "FAILED", detail)
