148	async def run_stage(stage, awaitable, success_detail=""):
149	    log_stage(stage, "START")
150	    try:
151	        result = await awaitable
152	    except BaseException as exc:
153	        log_stage_failure(stage, exc)
154	        raise
155	    log_stage(stage, "OK", success_detail)
156	    return result
