170	async def scan_for_exact_address(scanner_type, address, timeout):
171	    scanner = scanner_type()
172	    await scanner.start()
173	    try:
174	        await asyncio.sleep(timeout)
175	    finally:
176	        await scanner.stop()
177	
178	    target = normalize_ble_address(address)
179	    discovered = scanner.discovered_devices_and_advertisement_data
180	    matches = []
181	    for device, advertisement in discovered.values():
182	        if normalize_ble_address(device.address) == target:
183	            matches.append((device, advertisement))
184	
185	    if not matches:
186	        addresses = sorted(
187	            {
188	                f"{device.address} ({device.name or 'unknown'})"
189	                for device, _advertisement in discovered.values()
190	            }
191	        )
192	        visible = ", ".join(addresses) if addresses else "none"
193	        raise LookupError(
194	            f"target address {address!r} was not found during the "
195	            f"{timeout:g}s scan; discovered={visible}"
196	        )
197	
198	    for device, advertisement in matches:
199	        print(
200	            "[scan:match] "
201	            f"address={device.address!r} name={device.name!r} "
202	            f"rssi={getattr(advertisement, 'rssi', None)!r}",
203	            flush=True,
204	        )
205	    return matches[0][0]
