208	async def discover_probe_service(client):
209	    try:
210	        services = client.services
211	    except Exception:
212	        get_services = getattr(client, "get_services", None)
213	        if get_services is None:
214	            raise
215	        services = await get_services()
216	
217	    service = services.get_service(SERVICE_UUID)
218	    if service is None:
219	        raise LookupError(f"required GATT service {SERVICE_UUID} was not found")
220	    if services.get_characteristic(RX_UUID) is None:
221	        raise LookupError(f"required RX characteristic {RX_UUID} was not found")
222	    if services.get_characteristic(TX_UUID) is None:
223	        raise LookupError(f"required TX characteristic {TX_UUID} was not found")
224	    return services
