2174	{
2175	  static const uint16_t retry_delays_ms[PROBE_GESTURE_MAX_SENDS] =
2176	    {
2177	      500, 1000, 2000
2178	    };
2179	  struct probe_gesture_record_s *record;
2180	  uint8_t event[PROBE_GESTURE_EVENT_SIZE];
2181	  uint64_t now_ms;
2182	  uint32_t generation;
2183	  uint16_t packet_id = 0;
2184	  uint8_t send_count = 0;
2185	  bool send = false;
2186	  bool dropped = false;
2187	  bt_status_t status;
2188	
2189	  if (probe_monotonic_ms(&now_ms) < 0)
2190	    {
2191	      return;
2192	    }
2193	
2194	  pthread_mutex_lock(&g_state_lock);
2195	  generation = __atomic_load_n(&g_connection_generation, __ATOMIC_ACQUIRE);
2196	  if (g_gesture_rx_tail != g_gesture_rx_head)
2197	    {
2198	      record = &g_gesture_queue[g_gesture_rx_tail %
2199	                                PROBE_GESTURE_QUEUE_DEPTH];
2200	      if (!g_peer_connected || !g_notify_enabled ||
2201	          record->connection_generation != generation)
2202	        {
2203	          if (record->connection_generation != generation)
2204	            {
2205	              g_gesture_rx_tail = g_gesture_rx_head;
2206	            }
2207	        }
2208	      else if (record->send_count == 0 || now_ms >= record->next_retry_ms)
2209	        {
2210	          if (record->send_count >= PROBE_GESTURE_MAX_SENDS)
2211	            {
2212	              packet_id = record->packet_id;
2213	              memset(record, 0, sizeof(*record));
2214	              g_gesture_rx_tail++;
2215	              g_gesture_dropped++;
2216	              dropped = true;
2217	            }
2218	          else
2219	            {
2220	              packet_id = record->packet_id;
2221	              memcpy(event, record->event, sizeof(event));
2222	              record->send_count++;
2223	              send_count = record->send_count;
2224	              record->next_retry_ms =
2225	                now_ms + retry_delays_ms[send_count - 1];
2226	              if (send_count > 1)
2227	                {
2228	                  g_gesture_retransmitted++;
2229	                }
2230	              send = true;
2231	            }
2232	        }
2233	    }
2234	  pthread_mutex_unlock(&g_state_lock);
2235	
2236	  if (dropped)
2237	    {
2238	      printf("openvela_ble_probe: gesture dropped packet_id=%u\n",
2239	             packet_id);
2240	      return;
2241	    }
2242	
2243	  if (!send)
2244	    {
2245	      return;
2246	    }
2247	
2248	  status = probe_notify(g_service_handle, event, sizeof(event));
2249	  if (status != BT_STATUS_SUCCESS)
2250	    {
2251	      pthread_mutex_lock(&g_state_lock);
2252	      g_gesture_tx_status_nonzero++;
2253	      pthread_mutex_unlock(&g_state_lock);
2254	    }
2255	
2256	  if (send_count > 1)
2257	    {
2258	      printf("openvela_ble_probe: gesture retransmit packet_id=%u "
2259	             "attempt=%u status=%d\n",
2260	             packet_id, send_count, status);
2261	    }
2262	}
