2599	static uint16_t probe_rx_written(gatts_handle_t srv_handle,
2600	                                 bt_address_t *addr,
2601	                                 uint16_t attr_handle,
2602	                                 const uint8_t *value,
2603	                                 uint16_t length,
2604	                                 uint16_t offset)
2605	{
2606	  struct probe_rx_slot_s *slot;
2607	  uint32_t generation;
2608	  uint32_t head;
2609	  uint32_t tail;
2610	  uint32_t used;
2611	
2612	  (void)srv_handle;
2613	  (void)attr_handle;
2614	
2615	  if (offset != 0 || length > PROBE_RX_FRAME_MAX)
2616	    {
2617	      __atomic_fetch_add(&g_rx_invalid_length, 1, __ATOMIC_RELAXED);
2618	      return 0;
2619	    }
2620	
2621	  generation = __atomic_load_n(&g_connection_generation, __ATOMIC_ACQUIRE);
2622	  head = __atomic_load_n(&g_rx_head, __ATOMIC_RELAXED);
2623	  tail = __atomic_load_n(&g_rx_tail, __ATOMIC_ACQUIRE);
2624	  used = head - tail;
2625	  if (used >= PROBE_RX_QUEUE_DEPTH)
2626	    {
2627	      __atomic_fetch_add(&g_rx_drop_full, 1, __ATOMIC_RELAXED);
2628	      return 0;
2629	    }
2630	
2631	  slot = &g_rx_queue[head % PROBE_RX_QUEUE_DEPTH];
2632	  memcpy(&slot->addr, addr, sizeof(slot->addr));
2633	  slot->connection_generation = generation;
2634	  slot->length = length;
2635	  slot->offset = offset;
2636	  memcpy(slot->value, value, length);
2637	  used++;
2638	  if (used >
2639	      __atomic_load_n(&g_rx_high_water, __ATOMIC_RELAXED))
2640	    {
2641	      __atomic_store_n(&g_rx_high_water, used, __ATOMIC_RELAXED);
2642	    }
2643	
2644	  /* Publish only after the complete slot is visible to the consumer. */
2645	
2646	  __atomic_store_n(&g_rx_head, head + 1, __ATOMIC_RELEASE);
2647	
2648	  __atomic_fetch_add(&g_rx_enqueued, 1, __ATOMIC_RELAXED);
2649	  sem_post(&g_rx_sem);
2650	  return length;
2651	}
